package com.example.demo.api;
import com.example.demo.model.*;import com.example.demo.repo.*;import com.example.demo.security.Sessions;import tools.jackson.databind.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/irrigation/recommendation") public class RecommendationController{
 private final CropRepo crops;private final IrrigationRepo logs;private final SoilRepo soil;private final ObjectMapper json=new ObjectMapper();public RecommendationController(CropRepo c,IrrigationRepo l,SoilRepo s){crops=c;logs=l;soil=s;}
 @GetMapping("/{cropId}") public Map<String,Object> recommend(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable Long cropId,@RequestParam(required=false)Integer soilMoisture){Long uid=Sessions.user(auth);if(uid==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);Crop crop=crops.findByIdAndFarmOwnerId(cropId,uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));List<SoilMeasurement> measures=soil.findByCropIdAndCropFarmOwnerIdOrderByMeasurementDateDesc(cropId,uid);int moisture=soilMoisture!=null?soilMoisture:(measures.isEmpty()?-1:measures.getFirst().moisturePercentage);if(moisture<0)return Map.of("recommendation","Enter a soil-moisture reading","explanation","I need a current manual measurement to estimate irrigation needs.","weatherAvailable",false,"nextCheck","After measuring moisture");int threshold=switch(crop.cropType.toLowerCase()){case "tomato"->35;case "potato"->30;case "corn"->33;case "wheat"->28;case "pepper"->32;default->33;};String stage=crop.growthStage.toLowerCase();if(stage.contains("flower")||stage.contains("fruit")||stage.contains("heading"))threshold+=5;else if(stage.contains("matur")||stage.contains("senesc"))threshold-=3;int rain=0;double temp=0;boolean weatherAvailable=false;String weatherError="Weather forecast unavailable";try{String url="https://api.open-meteo.com/v1/forecast?latitude=29.987&longitude=31.211&current=temperature_2m&hourly=precipitation_probability&forecast_days=1";var req=java.net.http.HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(5)).GET().build();var res=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()==200){JsonNode root=json.readTree(res.body());temp=root.path("current").path("temperature_2m").asDouble();rain=root.path("hourly").path("precipitation_probability").path(0).asInt(0);weatherAvailable=true;}}catch(Exception ignored){}
 List<IrrigationLog> prior=logs.findByCropIdAndCropFarmOwnerIdOrderByIrrigationDateDesc(cropId,uid);boolean recentlyWatered=!prior.isEmpty()&&prior.getFirst().irrigationDate.isAfter(Instant.now().minus(Duration.ofHours(12)));String rec,why,next;if(moisture<threshold){if(rain>=60&&moisture>=threshold-8){rec="Recheck before watering";why="Soil moisture is near the crop-stage guide, and rain is likely soon.";next="In 4–6 hours";}else if(recentlyWatered&&moisture>=threshold-8){rec="Recheck soil before adding water";why="A recent irrigation was recorded. Moisture is close to the crop-stage guide.";next="In 4 hours";}else{rec="Check irrigation today";why="Soil moisture is below the "+crop.cropType+" guide ("+threshold+"%). "+(temp>35?"High heat may increase water demand. ":"")+(weatherAvailable?"Rain probability is "+rain+"%.":"Weather is unavailable; use local conditions to decide.");next=temp>35?"This afternoon":"Within the next few hours";}}else{rec="No irrigation indicated now";why="Moisture is at or above the crop-stage guide ("+threshold+"%). "+(weatherAvailable?"Rain probability is "+rain+"%.":"Weather data is unavailable.");next=recentlyWatered?"Recheck tomorrow after recent irrigation":"Recheck soil tomorrow";}return Map.ofEntries(Map.entry("cropId",cropId),Map.entry("cropType",crop.cropType),Map.entry("growthStage",crop.growthStage),Map.entry("soilMoisture",moisture),Map.entry("guideThreshold",threshold),Map.entry("temperature",temp),Map.entry("rainProbability",rain),Map.entry("weatherAvailable",weatherAvailable),Map.entry("recommendation",rec),Map.entry("explanation",why),Map.entry("nextCheck",next));}
}


